-- User-authorized fictional characters, clearly labeled. No Auth identities,
-- fabricated engagement, or attribution to actual members. Photos are illustrative.
INSERT INTO public.community_posts(id,author_id,author_name,author_badge,author_avatar,category,title,content,image_url,likes_count,comments_count,comments)
SELECT md5('coremotion-fictional-v1:' || title)::uuid,NULL,name,'Perfil fictício · Demonstração','/community/fictional-avatar.svg',category,title,
content || E'\n\nPublicação de personagem fictício para demonstração. Imagem ilustrativa; não retrata o autor nem comprova o relato.',image,0,0,'[]'::jsonb
FROM (VALUES
('Lia Monteiro','treino','Corrida no parque: mais constância, menos pressa','Uma ideia para conversar: reservar um horário possível na semana pode ajudar mais do que tentar copiar o ritmo de outra pessoa. Vocês preferem correr de manhã ou no fim do dia? Como adaptam a rotina quando chove?','https://images.unsplash.com/photo-1552674605-db6ffd4facb5?w=1000&q=80'),
('Rafael Nogueira','equipamento','Pedal urbano: o que não pode faltar na mochila?','Ferramentas básicas, água, identificação e iluminação entram no planejamento de muitos ciclistas. O que vocês consideram indispensável em um trajeto curto? Compartilhem soluções que respeitem as regras de trânsito e a segurança de quem pedala.','https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=1000&q=80'),
('Camila Azevedo','duvida','Natação: como escolher os primeiros óculos?','Conforto, vedação e ajuste costumam gerar dúvidas de quem começa na piscina. O que vocês observam ao experimentar um modelo? Contem o tipo de uso e evitem compartilhar lentes corretivas sem orientação adequada.','https://images.unsplash.com/photo-1519315901367-f34ff9154487?w=1000&q=80'),
('Bruno Valença','treino','Musculação: vocês registram os treinos?','Caderno, aplicativo ou memória: como vocês acompanham exercícios e conversam sobre a evolução com o treinador? A proposta é trocar formas de organização, não indicar cargas ou uma ficha única para todo mundo.','https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=1000&q=80'),
('Marina Duarte','equipamento','Futebol entre amigos: como escolher a bola para a superfície?','Campo, quadra e society pedem atenção às especificações de uso do fabricante. Além do preço, o que seu grupo considera na compra? Vale comentar durabilidade e cuidados depois da partida, deixando claro o modelo utilizado.','https://images.unsplash.com/photo-1579952363873-27f3bade9f55?w=1000&q=80'),
('Diego Amaral','duvida','Primeira aula de luta: como se preparar sem comprar tudo antes?','Antes de investir em equipamentos, conversar com a academia sobre a modalidade, a aula experimental e os itens exigidos pode evitar compras erradas. Que perguntas vocês fariam ao professor? Higiene, regras e respeito aos limites do parceiro também importam.','https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=1000&q=80'),
('Sofia Tavares','evento','Treino coletivo: como acolher quem está começando?','Esta é uma conversa sobre organização, não um convite para um evento marcado. Como definir pontos de encontro públicos, níveis de esforço e pausas para ninguém ficar sem apoio? Não publiquem endereços pessoais ou contatos de terceiros.','https://images.unsplash.com/photo-1517649763962-0c623266ddc0?w=1000&q=80'),
('Lucas Ferraz','conquista','Qual pequeno avanço você quer celebrar hoje?','Aprender um movimento, voltar depois de uma pausa ou simplesmente encontrar uma atividade de que gosta pode ser uma conquista. O espaço está aberto para histórias reais de vocês, sem competição de números ou pressão por recordes.','https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=1000&q=80')
) AS topics(name,category,title,content,image)
ON CONFLICT(id) DO NOTHING;
